"""Formal-config-equivalent, non-training GTSRB malicious-client coverage audit."""
import sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
import yaml, torch
from torch.utils.data import DataLoader, Subset
from data.dataset import load_dataset
from data.partition import partition_iid
from models.resnet18 import build_resnet18
from attacks.prototype import collect_class_statistics, aggregate_class_statistics
ROOT=Path(__file__).resolve().parents[1]; CFG=ROOT/'configs/final_gtsrb_cross_dataset_60_150_r350/gtsrb_pbu_s60_e150_r350.yaml'; OUT=ROOT/'outputs/saved_results/gtsrb_precheck_20260912/GTSRB_FORMAL_PREFLIGHT_COVERAGE_REPORT.md'
def main():
 c=yaml.safe_load(CFG.read_text()); train,_=load_dataset(c['dataset']['name'],ROOT/'datasets',False); p=partition_iid(len(train),c['partition']['num_clients'],c['experiment']['seed']); pc=c['attack']['trigger']['adversarial']['prototype_contrastive']; dev=torch.device('cuda' if torch.cuda.is_available() else 'cpu'); m=build_resnet18(43).to(dev); lines=['# GTSRB formal preflight coverage','', 'precheck uses formal training path = true'] ; best=[]
 for cid in [0,1,2]:
  loader=DataLoader(Subset(train,p[cid]),batch_size=c['training']['batch_size'],shuffle=True,num_workers=c['training']['num_workers']); s=collect_class_statistics(m,loader,dev,pc['feature_layer'],pc['center_batches']); b,d=aggregate_class_statistics([s],0,1,43,'skip'); valid=len(d['classes_covered']); missing=d['missing_classes']; lines += [f'- client{cid}: label/prototype coverage={valid}/43, missing={missing}, prototype_shape={tuple(b["prototypes"].shape)}, samples_per_class={[s["class_counts"].get(i,0) for i in range(43)]}']; best.append((valid,cid,missing))
 best.sort(key=lambda x:(-x[0],x[1])); chosen=best[0]; lines += [f'- recommended prototype_source_client={chosen[1]}', f'- PBU ready={chosen[0]==43}', '- Prototype tensor is a full (43, 512) bank in the formal preflight aggregation path; the earlier (42,512) UAP log was generated by client0, not configured client1.']; OUT.write_text('\n'.join(lines)+'\n');print('\n'.join(lines))
